function mdSeason(d){let y=d.getFullYear(),e=easter(y),ash=mdShift(e,-46),sept=mdShift(e,-63),palm=mdShift(e,-7),passion=mdShift(e,-14),asc=mdShift(e,39),pent=mdShift(e,49),advent=adventOpening(y);
 if(mdCmp(d,advent)>=0&&d.getMonth()===11)return{label:'Advent',color:'violet',desc:'Watching and preparing for the coming of Christ.'};
 if(mdCmp(d,new Date(y,11,25))>=0||mdCmp(d,new Date(y,0,13))<=0)return{label:'Christmas and Epiphany',color:'white',desc:'Contemplating the Incarnation and manifestation of Our Lord.'};
 if(mdCmp(d,sept)>=0&&mdCmp(d,ash)<0)return{label:'Septuagesima',color:'violet',desc:'A season of preparation and penitence before Lent.'};
 if(mdCmp(d,ash)>=0&&mdCmp(d,e)<0)return{label:mdCmp(d,palm)>=0?'Holy Week':mdCmp(d,passion)>=0?'Passiontide':'Lent',color:'violet',desc:'Prayer, fasting, almsgiving and meditation on the Passion.'};
 if(mdCmp(d,e)>=0&&mdCmp(d,mdShift(e,7))<0)return{label:'Easter Octave',color:'white',desc:'The Church rejoices in the Resurrection.'};
 if(mdCmp(d,e)>=0&&mdCmp(d,pent)<=0)return{label:'Eastertide',color:'white',desc:'The risen Lord, Ascension, and the expectation of Pentecost.'};
 if(mdCmp(d,pent)>0&&mdCmp(d,mdShift(pent,7))<=0)return{label:'Pentecost Octave',color:'red',desc:'The gift of the Holy Ghost and the Pentecost octave.'};
 if(mdCmp(d,pent)>0&&mdCmp(d,advent)<0)return{label:'Time after Pentecost',color:'green',desc:'Growing in faith through the teaching of Christ.'};
 return{label:'Time after Epiphany',color:'green',desc:'The public life and teachings of Our Lord.'};}
