function mdFirstWeekday(y,m,weekday){let d=new Date(y,m,1);d.setDate(1+(weekday-d.getDay()+7)%7);return d}
function mdMonthSequence(start,count,weekday){let result=[],p=start.getFullYear()*12+start.getMonth();if(mdCmp(mdFirstWeekday(start.getFullYear(),start.getMonth(),weekday),start)<0)p++;for(let i=0;i<count;i++){let year=Math.floor((p+i)/12),month=(p+i)%12;result.push(mdFirstWeekday(year,month,weekday))}return result}
