// Larger texts are fetched on first use; the service worker keeps them for offline use.
const mdCache={},mdLoaded={};
function mdFetch(name){if(!mdCache[name])mdCache[name]=fetch('data/'+name+'.json').then(r=>{if(!r.ok)throw new Error(String(r.status));return r.json()}).then(d=>{mdLoaded[name]=d;return d}).catch(e=>{delete mdCache[name];throw e});return mdCache[name]}
function mdAsync(root,name,fn){const box=createEl('div');const wait=createEl('p','md-muted','Loading…');box.append(wait);root.append(box);const token=renderToken;mdFetch(name).then(d=>{if(token!==renderToken)return;wait.remove();fn(d,box)}).catch(()=>{wait.textContent='This text could not be loaded. Open the prayer book once while online so it is saved for offline use.'})}

// ── Liturgical day: Sunday names, Ember and Rogation Days, vigils ──
function mdOrd(n){const s=['th','st','nd','rd'],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0])}
function mdWeeks(a,b){return Math.round(mdCmp(a,b)/6048e5)}
function mdSundayName(d){if(d.getDay()!==0)return{};const y=d.getFullYear(),m=d.getMonth(),dt=d.getDate(),e=easter(y),adv=adventOpening(y),pent=mdShift(e,49);
 if(m===11&&dt>=25)return{name:'Sunday within the Octave of Christmas',rank:'II'};
 if(mdCmp(d,adv)>=0){const n=mdWeeks(d,adv)+1;return{name:mdOrd(n)+' Sunday of Advent'+(n===3?' (Gaudete)':''),rank:'I'}}
 if(m===0&&dt>=2&&dt<=5)return{name:'Most Holy Name of Jesus',rank:'II'};
 if(m===0&&dt>=7&&dt<=13)return{name:'Holy Family (Sunday after Epiphany)',rank:'II'};
 const w=mdWeeks(d,e);
 if(w<-9){let hf=new Date(y,0,7);while(hf.getDay()!==0)hf=mdShift(hf,1);return{name:mdOrd(mdWeeks(d,hf)+1)+' Sunday after Epiphany',rank:'II'}}
 const named={'-9':['Septuagesima Sunday','II'],'-8':['Sexagesima Sunday','II'],'-7':['Quinquagesima Sunday','II'],'-6':['1st Sunday of Lent','I'],'-5':['2nd Sunday of Lent','I'],'-4':['3rd Sunday of Lent','I'],'-3':['4th Sunday of Lent (Laetare)','I'],'-2':['Passion Sunday','I'],'-1':['Palm Sunday','I'],'0':['Easter Sunday','I'],'1':['Low Sunday','I'],'2':['2nd Sunday after Easter','II'],'3':['3rd Sunday after Easter','II'],'4':['4th Sunday after Easter','II'],'5':['5th Sunday after Easter','II'],'6':['Sunday after the Ascension','II'],'7':['Pentecost Sunday','I'],'8':['Trinity Sunday','I']};
 if(named[w])return{name:named[w][0],rank:named[w][1]};
 // The 24th Sunday after Pentecost is always the last; any extra Sundays take the unused Sundays after Epiphany.
 const k=mdWeeks(d,pent),K=mdWeeks(adv,pent)-1;
 if(k===K)return{name:'Last Sunday after Pentecost (24th)',rank:'II'};
 if(k<=23)return{name:mdOrd(k)+' Sunday after Pentecost',rank:'II'};
 return{name:mdOrd(k)+' Sunday after Pentecost (Mass of the '+mdOrd(6-(K-24)+(k-23))+' Sunday after Epiphany)',rank:'II'}}
function mdNextWeekday(d,wd){let x=mdShift(d,1);while(x.getDay()!==wd)x=mdShift(x,1);return x}
// rule '1960': the 1960 rubrics (September and December after the third Sunday); '1917': after Holy Cross and St. Lucy.
function mdEmberDays(y,rule){const e=easter(y),out=[];const week=w=>[0,2,3].forEach(k=>out.push(mdDayKey(mdShift(w,k))));week(mdShift(e,-39));week(mdShift(e,52));
 if(rule==='1917'){week(mdNextWeekday(new Date(y,8,14),3));week(mdNextWeekday(new Date(y,11,13),3))}else{let s=new Date(y,8,1);while(s.getDay()!==0)s=mdShift(s,1);week(mdShift(s,17));week(mdShift(adventOpening(y),17))}return out}
function mdDayFlags(d){const y=d.getFullYear(),e=easter(y),f=[],sun=d.getDay()===0;
 if(mdEmberDays(y,'1960').includes(mdDayKey(d)))f.push('Ember Day');
 let mark=new Date(y,3,25);if(mdSame(mark,e))mark=mdShift(e,2);if(mdSame(d,mark))f.push('Major Rogation');
 if([36,37,38].some(n=>mdSame(d,mdShift(e,n))))f.push('Minor Rogation');
 [[new Date(y,11,24),'Vigil of Christmas'],[mdShift(e,48),'Vigil of Pentecost'],[mdShift(e,38),'Vigil of the Ascension'],[new Date(y,5,23),'Vigil of St. John the Baptist'],[new Date(y,5,28),'Vigil of Sts. Peter and Paul'],[new Date(y,7,9),'Vigil of St. Lawrence'],[new Date(y,7,14),'Vigil of the Assumption']].forEach(([v,n])=>{if(mdSame(d,v)&&(!sun||n==='Vigil of Christmas'))f.push(n)});return f}
function mdObservance(d){const o=mdObservanceBase(d);o.flags=mdDayFlags(d);return o}
const mdLordII=['8-06','9-14','11-09'];

// ── Fast and abstinence, labelled by era ──
const mdEras={'1917':{short:'1917 Code',label:'1917 Code (in force until 1966)'},'1983':{short:'current law',label:'Current law (1983 Code)'}};
function mdHolyDay1917(d){const e=easter(d.getFullYear()),k=(d.getMonth()+1)+'-'+d.getDate();return['12-25','1-1','1-6','3-19','6-29','8-15','11-1','12-8'].includes(k)||mdSame(d,mdShift(e,39))||mdSame(d,mdShift(e,60))}
function mdFastDay(d,era){const y=d.getFullYear(),e=easter(y),ash=mdShift(e,-46),dow=d.getDay(),f={fast:false,abst:false,why:[]};
 if(era==='1983'){if(mdSame(d,ash)){f.fast=f.abst=true;f.why.push('Ash Wednesday')}else if(mdSame(d,mdShift(e,-2))){f.fast=f.abst=true;f.why.push('Good Friday')}else if(dow===5){const ob=mdObservanceBase(d);if(ob.rank==='I')f.why.push('Friday, but a solemnity: abstinence does not bind');else{f.abst=true;f.why.push('Friday (or another penance where the bishops allow)')}}return f}
 const inLent=mdCmp(d,ash)>=0&&mdCmp(d,e)<0;
 if(dow===0)return f;
 if(mdHolyDay1917(d)&&!inLent){f.why.push('Holy day of obligation: the law ceases');return f}
 if(inLent){f.fast=true;f.why.push(mdSame(d,ash)?'Ash Wednesday':'Lent');if(mdSame(d,ash)||dow===5||dow===6)f.abst=true;if(mdSame(d,mdShift(e,-1)))f.why.push('Holy Saturday')}
 if(mdEmberDays(y,'1917').includes(mdDayKey(d))){f.fast=f.abst=true;f.why.push('Ember Day')}
 [[mdShift(e,48),'Vigil of Pentecost'],[new Date(y,7,14),'Vigil of the Assumption'],[new Date(y,9,31),'Vigil of All Saints'],[new Date(y,11,24),'Vigil of Christmas']].forEach(([v,n])=>{if(mdSame(d,v)){f.fast=f.abst=true;f.why.push(n)}});
 if(dow===5&&!f.abst){f.abst=true;f.why.push('Friday')}
 return f}
function mdFastLabel(f){return f.fast&&f.abst?'Fast and abstinence':f.fast?'Fast (meat not forbidden)':f.abst?'Abstinence from meat':'No fast or abstinence'}
const mdFastRules=[
 {era:'1917',title:'Under the 1917 Code (1918–1966)',src:'Codex Iuris Canonici (1917), canons 1250–1254.',items:['Abstinence from flesh meat: all Fridays.','Fast and abstinence: Ash Wednesday, the Fridays and Saturdays of Lent, the Ember Days, and the vigils of Pentecost, the Assumption, All Saints and Christmas.','Fast only: the other days of Lent, Sundays excepted.','The law ceased on Sundays and on holy days of obligation outside Lent, and a vigil falling on a Sunday was not anticipated.','On Holy Saturday the fast and abstinence ended at noon (extended to midnight by the 1955 reform of Holy Week).','Fasting meant one full meal a day, with some food morning and evening according to approved local custom. It bound from the completed 21st year to the beginning of the 60th; abstinence from the completed 7th year.','Many countries had indults that relaxed these rules; local practice varied.']},
 {era:'1966',title:'Under Paenitemini (Pope Paul VI, 1966)',src:'Apostolic Constitution Paenitemini, 17 February 1966.',items:['Fast and abstinence: Ash Wednesday and Good Friday.','Abstinence: the other Fridays of the year, unless a holy day of obligation falls on them; bishops’ conferences could substitute other works of penance.','Abstinence bound from the age of 14; fasting from 21 to the beginning of the 60th year.']},
 {era:'1983',title:'Under the 1983 Code (current law)',src:'Codex Iuris Canonici (1983), canons 1249–1253.',items:['All Fridays and the season of Lent are penitential days and times.','Abstinence from meat, or another penance set by the bishops’ conference, on all Fridays unless a solemnity falls on them.','Fast and abstinence on Ash Wednesday and Good Friday.','Abstinence binds from the age of 14; fasting from 18 to the beginning of the 60th year.']}
];
const mdEucharisticFast=[
 ['1917 Code, canon 858 (until 1953)','A natural fast from midnight: no food or drink at all, not even water, before Holy Communion. Those in danger of death, and under conditions the sick, were excepted.'],
 ['1953 · Pius XII, Christus Dominus','Natural water no longer breaks the fast. Mitigations were granted for the sick, for evening Masses, and for those with heavy work or a long journey.'],
 ['1957 · Pius XII, Sacram Communionem','Three hours from solid food and alcoholic drink, and one hour from non-alcoholic drinks, before Communion. Water does not break the fast, and medicines may be taken.'],
 ['1964 · Paul VI','One hour from food and drink before Communion; water and medicine do not break the fast.'],
 ['1983 Code, canon 919 (current law)','One hour from any food or drink, except water and medicine, before Holy Communion. The elderly, the sick and those who care for them are excused.']
];

