let mdCatLesson=1,mdCatMode='read',mdCatShow=false;
const mdCatSteps=[1,3,7,14,30,60];
function renderCatechism(){let root=$('prayerContent');root.append(mdIntro('CATECHISMUS','The Baltimore Catechism','Questions and answers from the Baltimore Catechism No. 2 (1885). Read a lesson, then review: answers you know come back less often, answers you miss come back tomorrow. Nothing is scored.'));
 mdAsync(root,'catechism',(d,box)=>{let prog=mdLoad('md-catechism',{});if(!prog||typeof prog!=='object'||Array.isArray(prog))prog={};
  let cards=[],n=0;d.lessons.forEach(l=>l.qa.forEach(([q,a])=>{n++;cards.push({id:String(n),n,lesson:l.n,q,a})}));
  const due=cards.filter(c=>prog[c.id]?prog[c.id].due<=todayKey:c.lesson===mdCatLesson);
  let tabs=createEl('div','md-tabs');d.lessons.forEach(l=>tabs.append(mdButton('Lesson '+l.n+' · '+l.title,()=>{mdCatLesson=l.n;mdCatMode='read';renderReader()},'md-tab'+(mdCatLesson===l.n&&mdCatMode==='read'?' active':''))));tabs.append(mdButton('Review · '+due.length+' due',()=>{mdCatMode='review';mdCatShow=false;renderReader()},'md-tab'+(mdCatMode==='review'?' active':'')));box.append(tabs);
  function grade(c,ok){const cur=prog[c.id]||{step:-1};const step=ok?Math.min(mdCatSteps.length-1,cur.step+1):0;prog[c.id]={step,due:mdDayKey(mdShift(todayMidnight,ok?mdCatSteps[step]:1))};mdStore('md-catechism',prog);mdCatShow=false;renderReader()}
  if(mdCatMode==='read'){const l=d.lessons.find(x=>x.n===mdCatLesson)||d.lessons[0];let p=mdPanel('Lesson '+l.n+' · '+l.title);cards.filter(c=>c.lesson===l.n).forEach(c=>{let qa=createEl('div','cat-qa');qa.append(createEl('p','cat-q',c.n+'. '+c.q),createEl('p','cat-a',c.a));p.append(qa)});p.append(mdButton('Review this lesson  ›',()=>{mdCatMode='review';mdCatShow=false;renderReader()}));box.append(p)}
  else{let p=mdPanel('Review','Say the answer to yourself, then reveal it.');if(!due.length)p.append(createEl('p',null,'Nothing is due today. Read another lesson, or come back tomorrow.'));else{const c=due[0];let card=createEl('div','cat-card');card.append(createEl('span','md-kicker','QUESTION '+c.n+' · LESSON '+c.lesson),createEl('p','cat-q',c.q));if(mdCatShow){card.append(createEl('p','cat-a',c.a));let row=createEl('div','md-inline');row.append(mdButton('I knew it',()=>grade(c,true)),mdButton('Not yet',()=>grade(c,false),'md-button outline'));card.append(row)}else card.append(mdButton('Show the answer',()=>{mdCatShow=true;renderReader()}));p.append(card,createEl('p','md-muted',due.length+(due.length===1?' question':' questions')+' left today'))}box.append(p)}
  box.append(mdNote('Source. '+d.source),mdNote(d.review))})}
function examList(title,sub,items){let p=mdPanel(title,sub);items.forEach(t=>{let label=createEl('label','md-exam-line'),box=createEl('input');box.type='checkbox';label.append(box,createEl('span',null,t));p.append(label)});return p}
function renderExamExtras(d,box){const L=d.lists;box.append(examList(L.precepts.title,'Baltimore Catechism (1885), as the precepts then stood. Ask a priest how they apply today.',L.precepts.items),examList(L.capital.title,'Baltimore Catechism (1885). Have I given way to any of these?',L.capital.items),examList(L.corporal.title+' · '+L.spiritual.title,'Baltimore Catechism (1885). Have I neglected any of these when I could have done them?',[...L.corporal.items,...L.spiritual.items]))}
function mdSpeak(text){if(!('speechSynthesis' in window)){toast('Listening is not available in this browser.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text.replace(/[✠\[\]]/g,''));u.lang='it-IT';const v=speechSynthesis.getVoices().find(x=>/^it/i.test(x.lang));if(v)u.voice=v;u.rate=.85;speechSynthesis.speak(u)}

