function mdDialog(title,kicker){const opener=document.activeElement;let ov=createEl('div','auth-overlay md-dialog open');ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');ov.setAttribute('aria-label',title);let card=createEl('div','auth-card md-dialog-card');let close=createEl('button','auth-close','×');close.type='button';close.setAttribute('aria-label','Close');card.append(close,createEl('div','auth-kicker','✠  '+kicker),createEl('h3',null,title));ov.append(card);
 function key(e){if(e.key==='Escape')done()}function done(){ov.remove();document.removeEventListener('keydown',key);if(opener&&opener.focus)opener.focus()}
 close.addEventListener('click',done);ov.addEventListener('click',e=>{if(e.target===ov)done()});document.addEventListener('keydown',key);document.body.append(ov);return{card,done}}
function openSettings(){const {card}=mdDialog('Settings','PRAEFERENTIAE');
 function group(label,opts,cur,cb){let g=createEl('div','set-group');g.append(createEl('div','set-label',label));let seg=createEl('div','set-seg');seg.setAttribute('role','group');seg.setAttribute('aria-label',label);opts.forEach(([v,t])=>{let b=createEl('button','set-opt'+(cur===v?' selected':''),t);b.type='button';b.setAttribute('aria-pressed',String(cur===v));b.addEventListener('click',()=>{cb(v);[...seg.children].forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});seg.append(b)});g.append(seg);card.append(g)}
 group('Appearance',[['auto','Match device'],['light','Light'],['dark','Dark']],settings.theme,v=>{settings.theme=v;saveSettings()});
 group('Prayer language',[['en','English'],['la','Latin'],['both','Side by side']],language,v=>{language=v;saveSettings();renderReader()});
 group('Text size',[['16','Small'],['19','Normal'],['22','Large'],['26','Largest']],String(fontSize),v=>{fontSize=+v;saveSettings()});
 group('Rubrics for the Office and Mass propers',Object.entries(mdRubrics).map(([k,r])=>[k,r.label]),settings.rubrics,v=>{settings.rubrics=v;saveSettings();renderReader()});
 group('Fasting rules shown on Today',Object.entries(mdEras).map(([k,e])=>[k,e.label]),settings.fastEra,v=>{settings.fastEra=v;saveSettings();renderReader()});
 let inst=createEl('div','set-group');inst.append(createEl('div','set-label','Install'));if(deferredInstall){inst.append(mdButton('Add Mediator Dei to this device',()=>{deferredInstall.prompt();deferredInstall=null}))}else inst.append(createEl('p','auth-note','Use your browser’s “Add to Home Screen” or “Install app”. Once opened, the prayer book works without a connection.'));card.append(inst);
 card.append(createEl('p','auth-note','Settings are kept on this device, and in your account when you are signed in.'));const first=card.querySelector('.set-opt');if(first)first.focus()}
function searchIndex(){let items=[],seen=new Set();[...sections.filter(s=>!s.direct),...tasks,...extraPages].forEach(t=>{if(seen.has(t.id)||t.id==='angelus06'||t.id==='angelus18')return;seen.add(t.id);items.push({title:t.id==='angelus12'?theAngelus:t.nav,sub:t.lat+(t.summary?' · '+t.summary:''),text:'',go:()=>go(t.id)})});
 Object.entries(data).forEach(([k,p])=>items.push({title:p.name,sub:p.latinTitle+' · Prayer library',text:(p.en||'')+' '+(p.la||''),go:()=>{treasuryFilter='All';treasuryQuery='';openedPrayer=k;mdJumpToPrayer=true;go('treasury','devotions')}}));
 const m=mdLoaded.mass;if(m)m.parts.forEach(p=>p.items.forEach(it=>items.push({title:it.t,sub:p.h+' · Ordinary of the Mass',text:(it.la||'')+' '+(it.en||''),go:()=>go('ordo','mass')})));
 const dv=mdLoaded.devotions;if(dv){dv.benediction.items.forEach(it=>items.push({title:it.t,sub:'Benediction',text:(it.la||'')+' '+(it.en||''),go:()=>go('benediction','devotions')}));dv.home.items.forEach(it=>items.push({title:it.t,sub:dv.home.title,text:(it.la||'')+' '+(it.en||''),go:()=>go('home','devotions')}))}
 const c=mdLoaded.catechism;if(c)c.lessons.forEach(l=>l.qa.forEach(([q,a])=>items.push({title:q,sub:'Baltimore Catechism · Lesson '+l.n,text:a,go:()=>{mdCatLesson=l.n;mdCatMode='read';go('catechism','learn')}})));
 return items}
function openSearch(){const {card,done}=mdDialog('Search the prayer book','QUAERITE ET INVENIETIS');let input=createEl('input','library-search');input.type='search';input.placeholder='A prayer, a devotion, a word…';input.setAttribute('aria-label','Search the prayer book');let out=createEl('div','search-results');out.setAttribute('aria-live','polite');card.append(input,out);
 function run(){const q=input.value.trim().toLowerCase();out.replaceChildren();if(q.length<2){out.append(createEl('p','md-muted','Type at least two letters. Press / anywhere to search.'));return}const words=q.split(/\s+/);const res=searchIndex().map(it=>{const head=(it.title+' '+it.sub).toLowerCase(),body=it.text.toLowerCase();if(!words.every(w=>head.includes(w)||body.includes(w)))return null;return{it,score:words.every(w=>head.includes(w))?2:1}}).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,30);if(!res.length){out.append(createEl('p','md-muted','Nothing found.'));return}res.forEach(({it})=>{let b=createEl('button','search-hit');b.type='button';b.append(createEl('strong',null,it.title),createEl('span',null,it.sub));b.addEventListener('click',()=>{done();it.go()});out.append(b)})}
 input.addEventListener('input',run);['mass','devotions','catechism'].forEach(n=>mdFetch(n).then(()=>{if(input.isConnected&&input.value)run()}).catch(()=>{}));input.focus();run()}

